"""DEVIATION_REPORT.html (all interpretive sentences derived from saved numbers)."""
import json, glob, base64, pandas as pd, numpy as np
OUT = 'outputs'; FIG = f'{OUT}/figures_dev'; D = f'{FIG}/plotted_data'
cap = json.load(open(f'{FIG}/captions_dev.json')); ref = json.load(open(f'{OUT}/dev/reference_diagnostics.json')); dec = json.load(open(f'{OUT}/dev/feasibility_decision.json')); app = json.load(open(f'{OUT}/dev/applicability.json')); rules = json.load(open(f'{OUT}/dev/decision_rules_result.json')); perm = rules['permutation']
SCR = pd.read_csv(f'{D}/summary_and_intervals.csv'); PAIR = pd.read_csv(f'{D}/paired_differences.csv'); ALL = pd.read_csv(f'{D}/all_metrics.csv'); CCS = pd.read_csv(f'{D}/complete_case_summary.csv'); REL = pd.read_csv(f'{D}/deviation_reliability.csv'); INC = pd.read_csv(f'{D}/reference_included_vs_excluded.csv'); COV = pd.read_csv(f'{D}/patient_coverage_vs_reference_train.csv')
img = lambda n, c=None: f'<figure><img src="data:image/png;base64,{base64.b64encode(open(f"{FIG}/{n}.png","rb").read()).decode()}" style="max-width:100%"><figcaption>{c or cap[n]}</figcaption></figure>'
fmt = lambda df: df.round(3).to_html(index=False, na_rep='undefined')
sm, au = ref['shape_mapping'], ref['uncentered_vs_amplitude_only']; r = SCR[(SCR.endpoint == 'Remitter') & (SCR.model == 'D')].iloc[0]; pr = PAIR[PAIR.endpoint == 'Remitter'].set_index('comparison'); cc = CCS[CCS.endpoint == 'Remitter'].set_index('model')
crit = pd.DataFrame([
 dict(criterion='F1 shape mapping improvement (GATING)', frozen_rule='ridge MSE < both baselines; both paired intervals exclude 0; relative reduction vs stronger baseline >= 5%', result=f'MSE {sm["aggregate_MSE"]["ridge_shape"]:.3f} vs mean-shape {sm["aggregate_MSE"]["a_mean_EO_shape"]:.3f} and persistence+shift {sm["aggregate_MSE"]["b_persistence_plus_mean_shift"]:.3f}; reductions {sm["vs_a_mean_shape"]["mean_reduction"]:.3f} [{sm["vs_a_mean_shape"]["reduction_ci"][0]:.3f}, {sm["vs_a_mean_shape"]["reduction_ci"][1]:.3f}] and {sm["vs_b_persistence"]["mean_reduction"]:.3f} [{sm["vs_b_persistence"]["reduction_ci"][0]:.3f}, {sm["vs_b_persistence"]["reduction_ci"][1]:.3f}]; relative vs stronger {100*sm["relative_reduction_vs_stronger"]:.0f}%', passed=dec['F1_shape_mapping_improvement']),
 dict(criterion='F3 deviation reliability (GATING)', frozen_rule='N>=100 eligible, median SB >= 0.50, >= 8/12 elements with lower bound >= 0.30', result=f'N={dec["n_eligible_both_conditions_ge5_windows_per_half"]}; median SB {dec["median_SB_deviation"]:.2f}; {dec["n_elements_lower_bound_ge_0_30"]}/12 lower bounds >= 0.30 (min lower bound {REL.deviation_lo.min():.2f})', passed=dec['F3_deviation_reliability']),
 dict(criterion='F2 uncentered vs amplitude-only (informational)', frozen_rule='interval excludes 0 and >= 5% relative reduction', result=f'reduction {au["mean_reduction"]:.3f} [{au["reduction_ci"][0]:.3f}, {au["reduction_ci"][1]:.3f}], {100*au["relative_reduction"]:.0f}%', passed=ref['criteria']['F2_uncentered_beats_amplitude_only_INFORMATIONAL']),
 dict(criterion='Coverage (informational)', frozen_rule='flag any variable < 80% inside reference 1st-99th percentile', result=f'min {app["coverage_min_pct"]:.0f}%, median {app["coverage_median_pct"]:.0f}%; {app["n_variables_below_80pct"]} variables flagged; max |SMD| {app["max_abs_SMD"]:.2f}', passed=app['n_variables_below_80pct'] == 0)])
claims = f'''<table><tr><th>Question</th><th>Evidence</th><th>Answer</th></tr>
<tr><td>1. Learned reference structure</td><td>Shape ridge cuts held-out MSE {100*sm["relative_reduction_vs_stronger"]:.0f}% below the stronger trivial baseline (persistence + mean shift); uncentered ridge cuts MSE {100*au["relative_reduction"]:.0f}% below an amplitude-only predictor.</td><td><b>Yes</b> (reference people only; previously examined evaluation set)</td></tr>
<tr><td>2. Reliable deviations</td><td>Median split-half SB {dec["median_SB_deviation"]:.2f} (all 12 lower bounds &ge; {REL.deviation_lo.min():.2f}); the simple contrast is as reliable ({dec["median_SB_contrast"]:.2f}).</td><td><b>Yes within a recording session</b> (halves of the same recording; not test-retest across days)</td></tr>
<tr><td>3. Remission prediction</td><td>D (levels + deviation) mean Remitter AUC {r.mean_auc:.3f} [{r.mean_auc_lo:.3f}, {r.mean_auc_hi:.3f}]; gain over E01c {r.gain_vs_E01c:+.3f} [{r.gain_lo:+.3f}, {r.gain_hi:+.3f}]; permutation p = {perm["p_value_plus_one"]:.3f}</td><td><b>No.</b> Funding rule not met; extension closed.</td></tr>
<tr><td>4. Does the learned reference add beyond levels / simple contrast?</td><td>D minus A {pr.loc["D - A"].mean_auc_diff:+.3f} [{pr.loc["D - A"].auc_lo:+.3f}, {pr.loc["D - A"].auc_hi:+.3f}]; D minus C {pr.loc["D - C"].mean_auc_diff:+.3f} [{pr.loc["D - C"].auc_lo:+.3f}, {pr.loc["D - C"].auc_hi:+.3f}]</td><td><b>Not supported</b> (frozen rule requires funding AND &ge;+0.05 with positive repeats and an interval excluding 0 versus each)</td></tr></table>'''
tabs = ''.join(f'<h3>{e}: all models and repeats</h3>' + fmt(ALL[ALL.endpoint == e][['model', 'seed', 'N', 'prevalence', 'AUC', 'AP', 'nPPV', 'sensitivity', 'PPV', 'balanced_accuracy', 'Brier', 'n_pos_calls', 'TP', 'FP', 'TN', 'FN']]) for e in ('Remitter', 'Responder'))
html = f'''<!doctype html><meta charset="utf-8"><title>EC to EO deviation experiment</title><style>body{{font:15px/1.5 system-ui;max-width:1080px;margin:2em auto;padding:0 1em}}figcaption{{font-size:13px;color:#333}}table{{border-collapse:collapse;font-size:11px}}td,th{{border:1px solid #ccc;padding:2px 5px;vertical-align:top}}.box{{background:#fff4e5;border-left:4px solid #D55E00;padding:.5em 1em}}code{{font-size:12px}}</style>
<h1>EC&rarr;EO centered-shape deviation: one bounded experiment (closed)</h1>
<div class="box"><b>Exploratory follow-up (DEVIATION_PROTOCOL.md, frozen before any shape diagnostic or remission scoring).</b> The learned reference structure is real and the deviations are reliable within a session, but they do <b>not</b> predict remission: candidate D failed the frozen funding rule (mean AUC {r.mean_auc:.3f}; gain over E01c {r.gain_vs_E01c:+.3f}), so this resting-power extension is closed. Better reconstruction alone did not establish reliable or predictive deviations, and reliable deviations did not establish prediction. Limitations preserved: same 164 patients already used four times; session 1 = pretreatment assumed (unverified); v2 cleaning has unresolved removals (drift-like and no-eye-evidence components) and 8 ICA failures.</div>
<h2>Three claims, kept distinct</h2>{claims}
<h2>Frozen criteria and results</h2>{fmt(crit)}
<h2>1. Mapping against stronger baselines (reference people; follow-up on an already examined set)</h2>{img("figF1_mapping_vs_baselines", "Held-out reference evaluation people (n=152, fixed partition; mapping fitted on 610 reference-training people with ridge alpha tuned only inside training). Left: paired held-out MSE reduction (ln-power squared) of the ridge versus each baseline with 95% bootstrap intervals over evaluation people (conditional on the fixed fit): shape ridge versus (a) the reference-training mean EO shape and (b) persistence plus mean EO-minus-EC shift; and, informational, the earlier uncentered mapping versus an amplitude-only predictor (OLS on mean EC log power). Middle/right: per-element held-out MSE. Shape = x - mean(x) of the 12 log powers (centered log-power shape, not conventional relative band power); level = mean(x) and can contain physiology as well as measurement effects. This is a follow-up on an already examined evaluation set.")}
<p>Identity check: the re-fitted uncentered mapping reproduces the previous stage exactly (alpha {ref["uncentered_identity_check"]["alpha"]}, mean R&sup2; {ref["uncentered_identity_check"]["mean_R2"]:.3f}). Level (overall amplitude) carries {100*ref["context"]["var_share_level_in_EO"]:.0f}% of the total across-person variance of the 12 EO log powers (shape the remaining {100-100*ref["context"]["var_share_level_in_EO"]:.0f}%), and EC and EO levels correlate {ref["context"]["corr_EC_EO_level"]:.2f}; the earlier R&sup2; of 0.805 was therefore largely a shared level, yet the uncentered ridge still beats amplitude-only by {100*au["relative_reduction"]:.0f}% MSE.</p>
<h2>2. Deviation reliability</h2>{img("figF2_deviation_reliability", f"Split-half reliability (Spearman-Brown corrected) across the {dec['n_eligible_both_conditions_ge5_windows_per_half']} evaluation people with disjoint recording portions (first vs second half of each recording's clean time span; linear band powers averaged over windows, then ln; fixed mapping from reference-training; deviations in reference cross-fitted residual SD units). Orange: deviation; blue: simple EO-minus-EC shape contrast; grey: EO shape alone. Bars: 95% bootstrap over people. Right: retained clean seconds per half (median {dec['retained_duration_s']['EC_half1_median']:.0f} s EC, {dec['retained_duration_s']['EO_half1_median']:.0f} s EO; minimum {dec['retained_duration_s']['min_any_half']:.0f} s). Both halves come from the same recording session, so this is within-session reliability.")}{fmt(REL.round(3))}
<h2>3. Reference applicability</h2>{img("figA1_coverage", "Patients versus reference-training: share of patients inside the reference-training 1st-99th percentile range (98% expected if identical; dashed line = 80% flag) and standardized mean differences, for the two levels and 24 shape elements. Descriptive only.")}
<p>Included reference people ({app["missingness"]["reference_complete"]} of {app["missingness"]["reference_people_listed"]}) differ from excluded ones (missing EC/EO features): excluded people are much younger (median age {INC[INC.group.str.startswith("excluded")].age_median.iloc[0]:.0f} vs {INC[INC.group=="reference-training"].age_median.iloc[0]:.0f}) with fewer clean windows (EC median {INC[INC.group.str.startswith("excluded")].clean_windows_EC_median.iloc[0]:.0f} vs {INC[INC.group=="reference-training"].clean_windows_EC_median.iloc[0]:.0f}); the reference is therefore a cleaner, adult-skewed subset. Patients (median age {app["missingness"]["patient_age_median"]:.0f}, {app["missingness"]["patient_female_pct"]:.0f}% female) resemble reference-training (median age {app["missingness"]["reference_train_age_median"]:.0f}, {app["missingness"]["reference_train_female_pct"]:.0f}% female). Missingness: {app["missingness"]["patients_either_incomplete"]} of {app["missingness"]["patients_total"]} patients have an incomplete EC or EO vector (EC {app["missingness"]["patients_EC_incomplete"]}, EO {app["missingness"]["patients_EO_incomplete"]}) versus {app["missingness"]["reference_pool_incomplete_pct"]:.0f}% of reference people. The reference mixes diagnoses (workbook-HEALTHY is a minority) and is a population reference, not a healthy norm; diagnoses and demographics were not used as predictors.{fmt(INC)}</p>
<h2>4. Remission models (A, B, C, D) against saved E01c</h2>{img("figV1_model_comparison")}{img("figV2_paired_differences")}{img("figV3_roc_pr")}{img("figV4_calibration")}
<p><b>Frozen decision rules.</b> Funding (D vs E01c): mean AUC &ge; 0.60 (D {rules["funding_D_vs_E01c"]["mean_AUC_D"]:.3f}), gain &ge; +0.05 ({rules["funding_D_vs_E01c"]["gain_vs_E01c"]:+.3f}), positive in every repeat ({rules["funding_D_vs_E01c"]["all_repeats_positive"]}): <b>{"met" if rules["funding_D_vs_E01c"]["met"] else "not met"}</b>. Learned-reference-helps claim: {"supported" if rules["learned_reference_helps"]["claim_supported"] else "not supported"}. Permutation (chance association of D only, {perm["n_perm"]} permutations, rng seed {perm["rng_seed"]}, folds regenerated from permuted labels, full refit, plus-one): observed {perm["observed_mean_AUC_D"]:.3f}, null mean {perm["null_mean"]:.3f}, 95th percentile {perm["null_q95"]:.3f}, p = {perm["p_value_plus_one"]:.3f}; <i>not</i> a test of incremental value or superiority.</p>
{tabs}<h3>Mean AUC and gain over E01c (conditional bootstrap)</h3>{fmt(SCR)}<h3>Paired differences (D minus each comparator)</h3>{fmt(PAIR)}
<h2>5. Complete-case sensitivity</h2>{img("figV5_complete_case")}<p>Remitter, patients with complete EC and EO vectors (N={dec and 153}): D {cc.loc["D"].auc_restricted_saved:.3f} (saved predictions restricted) / {cc.loc["D"].auc_refit_complete_only:.3f} (refit on complete cases); E01c restricted {cc.loc["E01c"].auc_restricted_saved:.3f}. The conclusion does not change.</p>{fmt(CCS)}
<h2>Limits and reproduction</h2><ul><li>Same 164 patients, previously used; bootstrap intervals are conditional on saved predictions and exclude training/tuning uncertainty; no multiplicity correction is claimed.</li><li>Session-1 timing unverified; v2 cleaning has unresolved removals and ICA failures; levels may contain measurement effects.</li><li>Reference evaluation set was already examined; reliability is within-session; the reference is a mixed-diagnosis, cleaner, adult-skewed population.</li><li>Models A&ndash;D use 2&ndash;24 features; E01c (65 features, corrected cleaning) remains the highest-scoring Remitter model (see table) but is itself not above chance by its own interval.</li></ul>
<p><b>Reproduce</b> (from first_tests/): <code>scripts/30_dev_window_powers.py; 29_dev_reference_mapping.py; 31_dev_reliability.py; 32_dev_applicability.py; 33_dev_outcomes.py; 34_dev_permutation.py; 35_dev_analysis.py; 36_dev_report.py</code> (helpers: dev.py). Configs: runs/DEV_*/config.json, runs/DEVcc_*/config.json.</p>'''
html = html.replace('N={dec and 153}', 'N=153'); open('DEVIATION_REPORT.html', 'w').write(html); print('ok', len(html) // 1000, 'KB')
